42	// 统计缓存信息
43	struct CacheStats {
44	    std::atomic<uint64_t> hits{0};
45	    std::atomic<uint64_t> misses{0};
46	
47	    double hitRate() const
48	    {
49	        uint64_t total = hits + misses;
50	        return total > 0 ? static_cast<double>(hits) / total : 0.0;
51	    }
52	
53	    void Reset()
54	    {
55	        hits = 0;
56	        misses = 0;
57	    }
58	};
59	
60	// 通信域缓存
61	class CommDomainCache {
62	public:
63	    explicit CommDomainCache(const std::string& commName) : commName_(commName) {}
64	
65	    const std::string& GetCommName() const { return commName_; }
66	
67	    // 获得缓存项，返回共享所有权保证使用期间对象稳定存活
68	    std::shared_ptr<const AlgResourceCtxSerializable> Get(const std::string& algTag)
69	    {
70	        std::lock_guard<std::mutex> lock(mutex_);
71	        auto it = cache_.find(algTag);
72	        return it != cache_.end() ? it->second : nullptr;
73	    }
74	
75	    // 缓存算法
76	    void Put(const std::string& algTag, const AlgResourceCtxSerializable& value)
77	    {
78	        std::lock_guard<std::mutex> lock(mutex_);
79	        cache_[algTag] = std::make_shared<AlgResourceCtxSerializable>(value);
80	    }
81	
82	    // 移除特定算法
83	    bool Remove(const std::string& algTag)
84	    {
85	        std::lock_guard<std::mutex> lock(mutex_);
86	        return cache_.erase(algTag) > 0;
87	    }
88	
89	    // 清空所有缓存项
90	    void Clear()
91	    {
92	        std::lock_guard<std::mutex> lock(mutex_);
93	        cache_.clear();
94	    }
95	
96	    CacheStats& GetStats() { return stats_; }
97	    const CacheStats& GetStats() const { return stats_; }
98	
99	    size_t GetCacheSize() const
100	    {
101	        std::lock_guard<std::mutex> lock(mutex_);
102	        return cache_.size();
103	    }
104	
105	private:
106	    std::string commName_;
107	    std::map<std::string, std::shared_ptr<const AlgResourceCtxSerializable>> cache_;
108	    CacheStats stats_;
109	    mutable std::mutex mutex_;
110	};
111	
112	// 通信域缓存管理器
113	class CommDomainCacheManager {
114	public:
115	    // 获取算法缓存
116	    std::shared_ptr<const AlgResourceCtxSerializable> Get(const std::string& algTag, const std::string& paramCommName)
117	    {
118	        std::string commName = ExtractCommName(algTag);
119	        // 提取失败时使用参数中的commName
120	        if (commName.empty())
121	            commName = paramCommName;
122	
123	        auto commCache = GetOrCreateComm(commName);
124	        if (commCache) {
125	            auto& stats = commCache->GetStats();
126	            auto result = commCache->Get(algTag);
127	            if (result) {
128	                stats.hits++;
129	                return result;
130	            }
131	            stats.misses++;
132	        }
133	        return nullptr;
134	    }
135	
136	    // 缓存算法结果
137	    void Put(const std::string& algTag, const AlgResourceCtxSerializable& value, const std::string& paramCommName)
138	    {
139	        std::string commName = ExtractCommName(algTag);
140	        if (commName.empty())
141	            commName = paramCommName;
142	
143	        auto commCache = GetOrCreateComm(commName);
144	        if (commCache) {
145	            commCache->Put(algTag, value);
146	        }
147	    }
148	
149	    // 释放通信域缓存
150	    bool ReleaseComm(const std::string& commName)
151	    {
152	        std::lock_guard<std::mutex> lock(mapMutex_);
153	        return commCaches_.erase(commName) > 0;
154	    }
155	
156	    // 获得通信域统计信息
157	    bool GetCommStats(const std::string& commName, CacheStats& outStats, size_t& outCacheSize) const
158	    {
159	        std::lock_guard<std::mutex> lock(mapMutex_);
160	        auto it = commCaches_.find(commName);
161	        if (it != commCaches_.end()) {
162	            outStats.hits = it->second->GetStats().hits.load();
163	            outStats.misses = it->second->GetStats().misses.load();
164	            outCacheSize = it->second->GetCacheSize();
165	            return true;
166	        }
167	        return false;
168	    }
169	
170	    // 获得全局统计信息
171	    void GetGlobalStats(
172	        size_t& totalCommDomains, size_t& totalcacheEntries, uint64_t& totalHits, uint64_t& totalMisses) const
173	    {
174	        std::lock_guard<std::mutex> lock(mapMutex_);
175	        totalCommDomains = commCaches_.size();
176	        totalcacheEntries = 0;
177	        totalHits = 0;
178	        totalMisses = 0;
179	        for (const auto& pair : commCaches_) {
180	            const auto& commName = pair.first;
181	            const auto& commCache = pair.second;
182	            totalcacheEntries += commCache->GetCacheSize();
183	            totalHits += commCache->GetStats().hits.load();
184	            totalMisses += commCache->GetStats().misses.load();
185	        }
186	    }
187	
188	    // 清空所有缓存
189	    void ClearAll()
190	    {
191	        std::lock_guard<std::mutex> lock(mapMutex_);
192	        commCaches_.clear();
193	    }
194	
195	    // 从algTag中提取通信域名称
196	    std::string ExtractCommName(const std::string& algTag)
197	    {
198	        size_t firstUnderscore = algTag.find('_');
199	        if (firstUnderscore == std::string::npos)
200	            return "";
201	
202	        size_t secondUnderscore = algTag.find('_', firstUnderscore + 1);
203	        if (secondUnderscore == std::string::npos)
204	            return "";
205	
206	        return algTag.substr(firstUnderscore + 1, secondUnderscore - firstUnderscore - 1);
207	    }
208	
209	private:
210	    // 获取或创建通信域缓存
211	    std::shared_ptr<CommDomainCache> GetOrCreateComm(const std::string& commName)
212	    {
213	        std::lock_guard<std::mutex> lock(mapMutex_);
214	        auto it = commCaches_.find(commName);
215	        if (it != commCaches_.end()) {
216	            return it->second;
217	        }
218	        auto result = commCaches_.emplace(commName, std::make_shared<CommDomainCache>(commName));
219	        return result.first->second;
220	    }
221	
222	    mutable std::mutex mapMutex_;
223	    std::map<std::string, std::shared_ptr<CommDomainCache>> commCaches_;
224	};
