241	// A5芯片或者template名称前缀为"opv2_"（当前A2的HostNic Send/Recv使用）走新流程，其他芯片走老流程
242	bool IsOpsV2(const char* algName, HcclDevType deviceType)
243	{
244	    // 检查algName前缀是否为"opv2_"
245	    if (algName != nullptr) {
246	        const char* prefix = "opv2_";
247	        if (strncmp(algName, prefix, strlen(prefix)) == 0) {
