261	inline HcclResult EnforceLaunchTask(const char* algTag)
262	{
263	    if (HcommBatchModeEnd(algTag) != HCCL_SUCCESS) {
264	        HCCL_ERROR("failed set eager mode, tag is %s.", algTag);
265	        return HCCL_E_INTERNAL;
266	    }
267	    if (HcommBatchModeStart(algTag) != HCCL_SUCCESS) {
268	        HCCL_ERROR("failed set batch mode, tag is %s.", algTag);
269	        return HCCL_E_INTERNAL;
270	    }
271	    return HCCL_SUCCESS;
272	}
273	
274	inline HcclResult
275	OpOrchestrate(OpParam* param, const AlgResourceCtxSerializable* resCtxPtr, ThreadHandle thread, std::string& algName)
276	{
277	    // RTSQ等待时间: 与算子展开无关, 但resCtx固定该设置不会再变更
278	    if (HcommIsSupportHcommThreadResAcquireTimeOut()) {
279	        CHK_RET(HcclThreadResAcquireTimeOut(resCtxPtr->fullTimeout));
280	    }
281	
282	    // NotifyWait等待时间: 只在算子展开过程中使用
283	    if (HcommIsSupportHcommSetNotifyWaitTimeOut()) {
284	        CHK_RET(HcclSetNotifyWaitTimeOut(resCtxPtr->waitTimeout));
285	    }
286	
287	    // 主thread等待Host stream的通知
288	    u32 maxNotifyNum = resCtxPtr->notifyNumOnMainThread;
289	    if (!resCtxPtr->isHcclThreadAcquireWithConfigSupported) {
290	        for (u32 i = 0; i < resCtxPtr->notifyNumPerThread.size(); i++) {
291	            if (resCtxPtr->notifyNumPerThread[i] > maxNotifyNum) {
292	                maxNotifyNum = resCtxPtr->notifyNumPerThread[i];
293	            }
294	        }
295	    }
296	    HCCL_DEBUG(
297	        "[%s]Notify wait on thread[%llu], maxNotifyNum[%u], timeout[%u] s", __func__, thread, maxNotifyNum,
298	        resCtxPtr->waitTimeout);
299	    CHK_RET(HcclThreadNotifyWaitOnThreadDefault(thread, maxNotifyNum, resCtxPtr->waitTimeout));
300	
301	    // 设置执行超时时间: 用于NotifyWait, 只在算子展开过程中使用
302	    ExecTimeoutManager::Instance().SetExecTimeout(param->opConfig.execTimeout);
303	
304	    // 设置BatchTransfer是否可行: 只在算子展开过程中使用
305	    CHK_RET(InitHcommBatchTransferOnThreadSupported(resCtxPtr->isHcommBatchTransferOnThreadSupported));
306	
307	    // 根据算法名字获取executor: 只用于算子展开
308	    std::shared_ptr<InsCollAlgBase> executor = CollAlgExecRegistryV2::Instance().GetAlgExec(param->opType, algName);
309	    if (executor.get() == nullptr) {
310	        HCCL_ERROR("Fail to find executor for algName[%s]", algName.c_str());
311	        return HCCL_E_INTERNAL;
312	    }
313	
314	    // 执行算法编排: 只用于算子展开
315	    if (executor->Orchestrate(*param, *resCtxPtr) != HCCL_SUCCESS) {
316	        HCCL_ERROR("orchestrate failed for alg:%s", param->algName);
317	        return HCCL_E_INTERNAL;
318	    }
319	
320	    return HCCL_SUCCESS;
321	}
322	
323	static HcclResult HcclOrderLaunchNotifyRecord(const OpParam* param)
324	{
325	    ThreadHandle exportHostOrderThread = param->exportHostOrderThread;
326	    ThreadHandle deviceOrderThread = param->deviceOrderThread;
327	    HCCL_INFO(
328	        "[%s]. Before Notify1 Record, commName[%s], exportHostOrderThread is [0x%llx], deviceOrderThread is [0x%llx]",
329	        __func__, param->commName, exportHostOrderThread, deviceOrderThread);
330	
331	    if (exportHostOrderThread != 0 && deviceOrderThread != 0) {
332	        CHK_RET(static_cast<HcclResult>(
333	            HcommThreadNotifyRecordOnThread(deviceOrderThread, exportHostOrderThread, HOST_ORDER_THREAD_NOTIFY_IDX)));
334	        HCCL_INFO(
335	            "[%s]. After Notify1 Record deviceOrderThread is [0x%llx], exportHostOrderThread is [0x%llx]", __func__,
336	            deviceOrderThread, exportHostOrderThread);
337	    }
338	
339	    return HCCL_SUCCESS;
340	}
341	
342	extern "C" unsigned int HcclLaunchAicpuKernel(OpParam* param)
343	{
344	    // 修改当前进程的调度策略和优先级
345	    struct sched_param schedParam;
346	    schedParam.sched_priority = 0; // 设置优先级为0
347	    if (sched_setscheduler(0, SCHED_OTHER, &schedParam) == -1) {
348	        HCCL_ERROR("%s sched_setscheduler to SCHED_OTHER failed", __func__);
349	        return 1;
350	    }
351	    if (param == nullptr) {
352	        HCCL_ERROR("%s param is nullptr", __func__);
353	        return 1;
354	    }
355	    HCCL_INFO("Entry-%s, commName[%s], tag[%s], algTag[%s]", __func__, param->commName, param->tag, param->algTag);
356	    if (HcommAcquireComm(param->commName) != HCCL_SUCCESS) {
357	        HCCL_ERROR("%s HcommAcquireComm fail, commName[%s]", __func__, param->commName);
358	        return 1;
359	    }
360	
361	    // AICPU 按序下发
362	    CHK_RET(HcclOrderLaunchNotifyRecord(param));
363	
364	    std::string algName = std::string(param->algName);
365	    if (!ops_hccl::IsOpsV2(param->algName, param->deviceType)) {
366	        ScatterOpInfo opInfo;
367	        if (CreateScatter(param, &opInfo) != HCCL_SUCCESS) {
368	            HCCL_ERROR("%s CreateScatter fail", __func__);
369	            return 1;
370	        }
371	
372	        if (HcommIsSupportHcommRegOpInfo()
373	            && HcommRegOpInfo(param->commName, reinterpret_cast<void*>(&opInfo), sizeof(ScatterOpInfo))
374	                   != HCCL_SUCCESS) {
375	            HCCL_ERROR(
376	                "%s HcommRegOpInfo fail, commName[%s], algTag[%s], size[%u]", __func__, param->commName, opInfo.algTag,
377	                sizeof(ScatterOpInfo));
378	            return 1;
379	        }
380	
381	        if (HcommIsSupportHcommRegOpTaskException()
382	            && HcommRegOpTaskException(param->commName, ops_hccl::GetScatterOpInfo) != HCCL_SUCCESS) {
383	            HCCL_ERROR(
384	                "%s HcommRegOpTaskException fail, commName[%s], algTag[%s]", __func__, param->commName, param->algTag);
385	            return 1;
386	        }
387	    }
388	
389	    if (ops_hccl::IsOpsV2(param->algName, param->deviceType)) {
390	        // 判断通信域状态
391	        HcclCommStatus commStatus = HCCL_COMM_STATUS_INVALID;
392	        if (HcommIsSupportHcclCommGetStatus()) {
393	            auto statusRet = HcclCommGetStatus(param->commName, &commStatus);
394	            if (statusRet != HCCL_SUCCESS) {
395	                HCCL_ERROR("%s HcclCommGetStatus fail, commName[%s], ret = %d", __func__, param->commName, statusRet);
396	                return 1;
397	            }
398	            if (commStatus == HCCL_COMM_STATUS_SUSPENDING) {
399	                if (HcommReleaseComm(param->commName) == HCCL_SUCCESS) {
400	                    HCCL_WARNING("%s commStatus is suspending, release commName[%s]", __func__, param->commName);
