836	        if (HcclDfxRegOpInfoByCommId(param->commName, (&dfxOpInfo)) != HCCL_SUCCESS) {
837	            HCCL_ERROR("HcclDfxRegOpInfoByCommId fail, commName is %s, tag is %s", param->commName, param->algTag);
838	            return 1;
839	        }
840	
841	        // 上报上报mainstream数据,第一个任务
842	        if (HcommProfilingReportKernelStartTask(thread, param->commName) != HCCL_SUCCESS) {
843	            HCCL_ERROR(
844	                "%sfailed to report MainStream And FirstTask, thread %lu, param->commName %s.", __func__, thread,
845	                param->commName);
846	            return 1;
847	        }
848	
849	        std::shared_ptr<InsCollAlgBase> executor = CollAlgExecRegistryV2::Instance().GetAlgExec(param->opType, algName);
850	        if (executor.get() == nullptr) {
851	            HCCL_ERROR(
852	                "Fail to find executor for algName[%s], opType[%d]", algName.c_str(), static_cast<int>(param->opType));
853	            HcommReleaseComm(param->commName);
854	            return 1;
855	        }
856	
857	        ExecTimeoutManager::Instance().SetExecTimeout(param->opConfig.execTimeout);
858	        HcclResult ret = HCCL_SUCCESS;
859	        ret = executor->OrchestrateWithThread(*param, *resCtxPtr, sendRecvThread);
860	        if (ret != HCCL_SUCCESS) {
861	            HCCL_ERROR("orchestrate failed for alg:%s, opType[%d]", param->algName, static_cast<int>(param->opType));
862	            HcommReleaseComm(param->commName);
863	            return 1;
864	        }
865	        // 上报mainstream数据,最后一个任务
866	        if (HcommProfilingReportKernelEndTask(thread, param->commName) != HCCL_SUCCESS) {
867	            HCCL_ERROR(
868	                "%s failed to report MainStream And LastTask, thread %lu, param->commName %s.", __func__, thread,
869	                param->commName);
870	            return 1;
871	        }
872	        if (HcommProfilingReportDeviceOp(param->commName) != HCCL_SUCCESS) {
873	            HCCL_ERROR("%s HcommProfilingReportDeviceOp fail, commName[%s]", __func__, param->commName);
874	            return 1;
875	        }
876	        if (HcommBatchModeEnd(param->algTag) != HCCL_SUCCESS) {
877	            HCCL_ERROR("failed set eager mode, tag is %s.", param->algTag);
878	            return 1;
879	        }
880	    } else {
881	        HCCL_ERROR(
882	            "%s P2P only support OpsV2, algName[%s], deviceType[%d]", __func__, param->algName,
883	            static_cast<int>(param->deviceType));
884	        HcommReleaseComm(param->commName);
885	        return 1;
886	    }
887	
888	    if (HcommReleaseComm(param->commName) != HCCL_SUCCESS) {
889	        HCCL_ERROR("%s HcommReleaseComm fail, commName[%s]", __func__, param->commName);
890	        return 1;
891	    }
892	    HCCL_INFO("%s success, tag[%s], algTag[%s], commName[%s]", __func__, param->tag, param->algTag, param->commName);
893	    return 0;
894	}
