978	extern "C" unsigned int HcclLaunchAicpuKernelA3(OpParam* param)
979	{
980	    if (param == nullptr) {
981	        HCCL_ERROR("%s param is nullptr", __func__);
982	        return 1;
983	    }
984	    HCCL_INFO("Entry-%s, commName[%s], tag[%s], algTag[%s]", __func__, param->commName, param->tag, param->algTag);
985	    if (HcommAcquireComm(param->commName) != HCCL_SUCCESS) {
986	        HCCL_ERROR("%s HcommAcquireComm fail, commName[%s]", __func__, param->commName);
987	        return 1;
988	    }
989	
990	    std::string algName = std::string(param->algName);
991	    if (!ops_hccl::IsOpsV2(param->algName, param->deviceType)) {
992	        ScatterOpInfo opInfo;
993	        if (CreateScatter(param, &opInfo) != HCCL_SUCCESS) {
994	            HCCL_ERROR("%s CreateScatter fail", __func__);
995	            return 1;
996	        }
997	
998	        if (HcommIsSupportHcommRegOpInfo()
999	            && HcommRegOpInfo(param->commName, reinterpret_cast<void*>(&opInfo), sizeof(ScatterOpInfo))
1000	                   != HCCL_SUCCESS) {
1001	            HCCL_ERROR(
1002	                "%s HcommRegOpInfo fail, commName[%s], algTag[%s], size[%u]", __func__, param->commName, opInfo.algTag,
1003	                sizeof(ScatterOpInfo));
1004	            return 1;
1005	        }
1006	
1007	        if (HcommIsSupportHcommRegOpTaskException()
1008	            && HcommRegOpTaskException(param->commName, ops_hccl::GetScatterOpInfo) != HCCL_SUCCESS) {
1009	            HCCL_ERROR(
1010	                "%s HcommRegOpTaskException fail, commName[%s], algTag[%s]", __func__, param->commName, param->algTag);
1011	            return 1;
1012	        }
1013	    }
1014	
1015	    // 根据算法名字获取executor
1016	    if (ops_hccl::IsOpsV2(param->algName, param->deviceType)) {
1017	        // 判断通信域状态
1018	        HcclCommStatus commStatus = HCCL_COMM_STATUS_INVALID;
1019	        if (HcommIsSupportHcclCommGetStatus()) {
1020	            auto statusRet = HcclCommGetStatus(param->commName, &commStatus);
1021	            if (statusRet != HCCL_SUCCESS) {
1022	                HCCL_ERROR("%s HcclCommGetStatus fail, commName[%s], ret = %d", __func__, param->commName, statusRet);
1023	                return 1;
1024	            }
1025	            if (commStatus == HCCL_COMM_STATUS_SUSPENDING) {
1026	                if (HcommReleaseComm(param->commName) == HCCL_SUCCESS) {
1027	                    HCCL_WARNING("%s commStatus is suspending, release commName[%s]", __func__, param->commName);
1028	                } else {
1029	                    HCCL_ERROR(
1030	                        "%s commStatus is suspending, HcommReleaseComm fail, commName[%s]", __func__, param->commName);
1031	                }
1032	                return 301U; /* 301U: AICPUSUSPENDING_ERROR */
1033	            }
1034	            if (commStatus != HCCL_COMM_STATUS_READY) {
1035	                HCCL_ERROR("%s commStatus is not ready!, commStatus = %d", __func__, static_cast<int>(commStatus));
1036	                return 1;
1037	            }
1038	        }
1039	
1040	        std::shared_ptr<const AlgResourceCtxSerializable> cachedResCtxHolder;
1041	        std::unique_ptr<AlgResourceCtxSerializable> resCtx;
1042	        const AlgResourceCtxSerializable* resCtxPtr{nullptr};
1043	        if (param->opType != HcclCMDType::HCCL_CMD_BATCH_SEND_RECV) {
1044	            // 通过缓存实现反序列化优化
1045	            cachedResCtxHolder = g_cacheManager.Get(param->algTag, param->commName);
1046	            if (cachedResCtxHolder != nullptr && IsResCtxCacheReusable(*cachedResCtxHolder, *param)) {
1047	                HCCL_INFO("[%s] Cache HIT for algTag[%s]", __func__, param->algTag);
1048	                std::string commName = g_cacheManager.ExtractCommName(param->algTag);
1049	                if (commName.empty())
1050	                    commName = param->commName;
1051	
1052	                CacheStats stats;
1053	                size_t cacheSize;
1054	                if (g_cacheManager.GetCommStats(commName, stats, cacheSize)) {
1055	                    HCCL_DEBUG(
1056	                        "[%s] comm[%s] hitRate=%.2f%%, cacheSize=%zu", __func__, commName.c_str(),
1057	                        stats.hitRate() * 100, cacheSize);
1058	                }
1059	                resCtxPtr = cachedResCtxHolder.get();
1060	            } else {
1061	                bool isStaleCache = (cachedResCtxHolder != nullptr);
1062	                // 未命中或者通信域恢复后缓存失效，进行反序列化并存入缓存
1063	                resCtx = DeserializeResCtx(param);
1064	                g_cacheManager.Put(param->algTag, *resCtx, param->commName);
1065	                resCtxPtr = resCtx.get();
1066	                if (isStaleCache) {
1067	                    HCCL_INFO(
1068	                        "[%s] Cache STALE and refreshed for algTag[%s], cachedComm[%p], currentComm[%p]", __func__,
1069	                        param->algTag, cachedResCtxHolder->commInfoPtr, param->hcclComm);
1070	                } else {
1071	                    HCCL_INFO("[%s] Cache MISS and stored for algTag[%s]", __func__, param->algTag);
1072	                }
1073	            }
1074	        } else {
1075	            resCtx = DeserializeResCtx(param);
1076	            resCtxPtr = resCtx.get();
1077	        }
1078	
1079	        // 还原变长指针
1080	        HcclResult ret = HCCL_SUCCESS;
1081	        if (param->opType == HCCL_CMD_BATCH_SEND_RECV) {
1082	            ret = ops_hccl::RestoreVarDataBatchSendRecv(*param);
1083	        } else if (
1084	            param->opType == HCCL_CMD_ALLTOALLV || param->opType == HCCL_CMD_ALLTOALLVC
1085	            || param->opType == HCCL_CMD_ALLTOALL) {
1086	            ret = ops_hccl::RestoreVarDataAlltoAllV(*param, *resCtxPtr);
1087	        } else if (param->opType == HCCL_CMD_REDUCE_SCATTER_V) {
1088	            ret = ops_hccl::RestoreVarDataReduceScatterV(*param, *resCtxPtr);
1089	        } else if (param->opType == HCCL_CMD_ALLGATHER_V) {
1090	            ret = ops_hccl::RestoreVarDataAllGatherV(*param, *resCtxPtr);
1091	        }
1092	        if (ret != HCCL_SUCCESS) {
1093	            HCCL_ERROR("failed to restore optype [%d] data and counts.", param->opType);
1094	            return 1;
1095	        }
1096	        // 获取Device测主thread
1097	        ThreadHandle thread = resCtxPtr->threads[0];
1098	        if (HcommBatchModeStart(param->algTag) != HCCL_SUCCESS) {
1099	            HCCL_ERROR("failed set batch mode, tag is %s.", param->algTag);
1100	            return 1;
1101	        }
1102	
1103	        // 要在下第一个task之前上报
1104	        HcclDfxOpInfoCompat dfxOpInfo{};
1105	        if (ConvertToHcclDfxOpInfo(param, &dfxOpInfo) != HCCL_SUCCESS) {
1106	            HCCL_ERROR("ConvertToHcclDfxOpInfo fail, commName is %s, tag is %s", param->commName, param->algTag);
1107	            return 1;
1108	        }
1109	        if (HcclDfxRegOpInfoByCommId(param->commName, reinterpret_cast<void*>(&dfxOpInfo)) != HCCL_SUCCESS) {
1110	            HCCL_ERROR("HcclDfxRegOpInfoByCommId fail, commName is %s, tag is %s", param->commName, param->algTag);
1111	            return 1;
1112	        }
1113	
1114	        // 上报上报mainstream数据,第一个任务
1115	        if (HcommProfilingReportKernelStartTask(thread, param->commName) != HCCL_SUCCESS) {
1116	            HCCL_ERROR(
1117	                "%sfailed to report MainStream And FirstTask, thread %lu, param->commName %s.", __func__, thread,
1118	                param->commName);
1119	            return 1;
1120	        }
1121	
1122	        // 主thread等待Host stream的通知
1123	        ThreadHandle exportedAicpuTsThread = param->opThread;
1124	        u32 maxNotifyNum = resCtxPtr->notifyNumOnMainThread;
1125	        for (u32 i = 0; i < resCtxPtr->notifyNumPerThread.size(); i++) {
1126	            if (resCtxPtr->notifyNumPerThread[i] > maxNotifyNum) {
1127	                maxNotifyNum = resCtxPtr->notifyNumPerThread[i];
1128	            }
1129	        }
1130	        HCCL_DEBUG(
1131	            "[%s]Notify wait on thread[%llu], maxNotifyNum[%u], timeout[%u] s", __func__, thread, maxNotifyNum,
1132	            CUSTOM_TIMEOUT);
1133	        CHK_RET(static_cast<HcclResult>(HcommThreadNotifyWaitOnThread(thread, maxNotifyNum, CUSTOM_TIMEOUT)));
1134	
1135	        std::shared_ptr<InsCollAlgBase> executor = CollAlgExecRegistryV2::Instance().GetAlgExec(param->opType, algName);
1136	        if (executor.get() == nullptr) {
1137	            HCCL_ERROR("Fail to find executor for algName[%s]", algName.c_str());
1138	            return 1;
1139	        }
1140	
1141	        // 设置执行超时时间
1142	        ExecTimeoutManager::Instance().SetExecTimeout(param->opConfig.execTimeout);
1143	        // 设置BatchTransfer是否可行
1144	        CHK_RET(InitHcommBatchTransferOnThreadSupported(resCtxPtr->isHcommBatchTransferOnThreadSupported));
1145	        // 执行算法编排
1146	        if (executor->Orchestrate(*param, *resCtxPtr) != HCCL_SUCCESS) {
1147	            HCCL_ERROR("orchestrate failed for alg:%s", param->algName);
1148	            return 1;
1149	        }
1150	
1151	        // 上报mainstream数据,最后一个任务
1152	        if (HcommProfilingReportKernelEndTask(thread, param->commName) != HCCL_SUCCESS) {
1153	            HCCL_ERROR(
1154	                "%s failed to report MainStream And LastTask, thread %lu, param->commName %s.", __func__, thread,
1155	                param->commName);
1156	            return 1;
1157	        }
1158	
1159	        constexpr u32 DEFAULT_NOTIFY_IDX = 0;
1160	        HCCL_DEBUG(
1161	            "[%s]Notify record on srcThread[%llu], dstThread[%llu], notifyIdx[%u]", __func__, thread,
1162	            exportedAicpuTsThread, DEFAULT_NOTIFY_IDX);
1163	        CHK_RET(static_cast<HcclResult>(
1164	            HcommThreadNotifyRecordOnThread(thread, exportedAicpuTsThread, DEFAULT_NOTIFY_IDX)));
1165	
1166	        if (HcommProfilingReportDeviceOp(param->commName) != HCCL_SUCCESS) {
1167	            HCCL_ERROR("%s HcommProfilingReportDeviceOp fail, commName[%s]", __func__, param->commName);
1168	            return 1;
1169	        }
1170	
1171	        if (HcommBatchModeEnd(param->algTag) != HCCL_SUCCESS) {
1172	            HCCL_ERROR("failed set eager mode, tag is %s.", param->algTag);
1173	            return 1;
1174	        }
1175	    } else {
1176	        std::unique_ptr<ExecutorBase> executor = CollAlgExecRegistry::Instance().GetAlgExec(algName);
1177	        if (executor.get() == nullptr) {
1178	            HCCL_ERROR("Fail to find executor for algName[%s]", algName.c_str());
1179	            return 1;
1180	        }
1181	        AlgResourceCtx* resCtx = reinterpret_cast<AlgResourceCtx*>(param->resCtx);
1182	        // 获取Device测主thread
1183	        ThreadHandle* threadHandlePtr
1184	            = reinterpret_cast<ThreadHandle*>(reinterpret_cast<u8*>(resCtx) + sizeof(AlgResourceCtx));
1185	        ThreadHandle thread = threadHandlePtr[0];
1186	        ThreadHandle exportedAicpuTsThread = resCtx->opThread;
1187	        u32 notifyNumOnMainThread = resCtx->notifyNumOnMainThread;
1188	        if (HcommBatchModeStart(param->algTag) != HCCL_SUCCESS) {
1189	            HCCL_ERROR("failed set batch mode, tag is %s.", param->algTag);
1190	            return 1;
1191	        }
1192	
1193	        if (exportedAicpuTsThread != 0) {
1194	            if (HcommProfilingInit(threadHandlePtr, resCtx->slaveThreadNum + 1) != HCCL_SUCCESS) {
1195	                HCCL_ERROR("failed to init Profiling");
1196	                return 1;
1197	            }
1198	
1199	            // 上报主流和第一个task  wait之前
1200	            if (HcommProfilingReportMainStreamAndFirstTask(thread) != HCCL_SUCCESS) {
1201	                HCCL_ERROR("failed to report MainStream And FirstTask");
1202	                return 1;
1203	            }
1204	
1205	            // 主thread等待Host stream的通知
1206	            HCCL_DEBUG(
1207	                "[%s]Notify wait on thread[%llu], notifyNumOnMainThread[%u], timeout[%u] s", __func__, thread,
1208	                notifyNumOnMainThread, CUSTOM_TIMEOUT);
1209	            CHK_RET(
1210	                static_cast<HcclResult>(HcommThreadNotifyWaitOnThread(thread, notifyNumOnMainThread, CUSTOM_TIMEOUT)));
1211	        } else {
1212	            if (HcommAclrtNotifyWaitOnThread(thread, resCtx->notifyIds[0], CUSTOM_TIMEOUT) != HCCL_SUCCESS) {
1213	                HCCL_ERROR("failed to wait notify[%d] from host main stream", resCtx->notifyIds[0]);
1214	                return 1;
1215	            }
1216	        }
1217	
1218	        // 执行算法编排
1219	        if (executor->Orchestrate(*param, resCtx) != HCCL_SUCCESS) {
1220	            HCCL_ERROR("orchestrate failed for alg:%s", param->algName);
1221	            return 1;
1222	        }
1223	
1224	        if (exportedAicpuTsThread != 0) {
1225	            // 上报device侧的op 附加信息
1226	            HcomProInfoTmp profInfo;
1227	            std::string algTypeStr(param->algTypeStr);
1228	            if (strcpy_s(profInfo.algType, sizeof(profInfo.algType), algTypeStr.c_str()) != EOK) {
1229	                HCCL_ERROR("[%s] strcpy_s profInfo.algType failed.", __func__);
1230	                return 1;
1231	            }
1232	            if (strcpy_s(profInfo.commName, sizeof(profInfo.commName), param->commName) != EOK) {
1233	                HCCL_ERROR("[%s] strcpy_s profInfo.commName failed.", __func__);
1234	                return 1;
1235	            }
1236	            profInfo.commNameLen = strlen(param->commName);
1237	            profInfo.dataCount = param->DataDes.count;
1238	            profInfo.dataType = static_cast<uint8_t>(param->DataDes.dataType);
1239	            profInfo.rankSize = resCtx->topoInfo.userRankSize;
1240	            HcommProfilingReportDeviceHcclOpInfo(profInfo);
1241	
1242	            // 主thread通知Host stream
1243	            constexpr u32 DEFAULT_NOTIFY_IDX = 0;
1244	            HCCL_DEBUG(
1245	                "[%s]Notify record on srcThread[%llu], dstThread[%llu], notifyIdx[%u]", __func__, thread,
1246	                exportedAicpuTsThread, DEFAULT_NOTIFY_IDX);
1247	            CHK_RET(static_cast<HcclResult>(
1248	                HcommThreadNotifyRecordOnThread(thread, exportedAicpuTsThread, DEFAULT_NOTIFY_IDX)));
1249	
1250	            // 上报主流和最后一个task 在notify之后
1251	            if (HcommProfilingReportMainStreamAndLastTask(thread) != HCCL_SUCCESS) {
1252	                HCCL_ERROR("failed to report MainStream And LastTask");
1253	                return 1;
1254	            }
1255	
1256	            if (HcommBatchModeEnd(param->algTag) != HCCL_SUCCESS) {
1257	                HCCL_ERROR("failed set eager mode, tag is %s.", param->algTag);
1258	                return 1;
1259	            }
1260	
1261	            if (HcommProfilingEnd(threadHandlePtr, resCtx->slaveThreadNum + 1) != HCCL_SUCCESS) {
1262	                HCCL_ERROR("failed to End Profiling");
1263	                return 1;
1264	            }
1265	        } else {
1266	            if (HcommAclrtNotifyRecordOnThread(thread, resCtx->notifyIds[1]) != HCCL_SUCCESS) {
1267	                HCCL_ERROR("failed to record host main stream");
1268	                return 1;
