    u64 size{0};
    u64 count{0};

    NHRSliceInfo(const u64 offset, const u64 size, const u64 count) : offset(offset), size(size), count(count) {}
};

class InsTempAllReduceNHR : public InsAlgTemplateBase {
public:
    InsTempAllReduceNHR() = default;
