30	HcclResult InsTempAllReduceNHR::CalcRes(
31	    HcclComm comm, const OpParam& param, const TopoInfoWithNetLayerDetails* topoInfo,
32	    AlgResourceRequest& resourceRequest)
33	{
34	    std::vector<HcclChannelDesc> level1Channels;
35	    if (topoInfo->level0Topo == Level0Shape::MESH_1D_CLOS && !topoInfo->level0PcieMix) {
36	        std::vector<HcclChannelDesc> myChannelDescs;
37	        CHK_RET(CalcChannelRequestNhrMultiJetty(comm, param, topoInfo, subCommRanks_, myChannelDescs));
38	        for (auto channel : myChannelDescs) {
39	            if (channel.channelProtocol == COMM_PROTOCOL_UBC_CTP) {
40	                level1Channels.push_back(channel);
41	            }
42	        }
43	        HCCL_DEBUG("[InsTempAllReduceNHR::CalcRes] Get Channel Success!");
44	    } else {
45	        CHK_RET(CalcChannelRequestNhr(comm, param, topoInfo, subCommRanks_, level1Channels));
46	    }
47	    resourceRequest.channels.push_back(level1Channels);
48	    channelsPerRank_ = CalcChannelsPerRank(level1Channels);
49	    if (channelsPerRank_ > MAX_JETTY_NUM) {
50	        HCCL_ERROR(
51	            " %s channelsPerRank_ %u is greater than MAX_JETTY_NUM %u", __func__, channelsPerRank_, MAX_JETTY_NUM);
52	    } else {
53	        HCCL_DEBUG(" %s channelsPerRank_ is %u ", __func__, channelsPerRank_);
54	    }
55	    GetRes(resourceRequest);
56	
57	    HCCL_INFO("[InsTempAllReduceNHR] Calculate resource finished.");
58	    return HcclResult::HCCL_SUCCESS;
59	}
