92	HcclResult InsTempAllReduceNHR::PrepareDataSplitForMultiChannel(const TemplateResource& templateResource)
93	{
94	    CHK_PRT_RET(
95	        templateResource.channels.empty() || templateResource.channels.begin()->second.empty(),
96	        HCCL_ERROR("[InsTempAllReduceNHR][PrepareDataSplitForMultiChannel] channels is empty."), HCCL_E_INTERNAL);
97	    std::vector<u64> elemCountOut;
98	    u64 totalDataCount = sliceSize_ / dataTypeSize_;
99	    CHK_RET(CalcDataSplitByPortGroup(
100	        totalDataCount, dataTypeSize_, templateResource.channels.begin()->second, elemCountOut, dataSplit_,
101	        dataOffset_));
102	    if (tailSize_ != sliceSize_ && tailSize_ > 0) {
103	        std::vector<u64> elemCountOutTail;
104	        u64 totalDataCountTail = tailSize_ / dataTypeSize_;
105	        CHK_RET(CalcDataSplitByPortGroup(
106	            totalDataCountTail, dataTypeSize_, templateResource.channels.begin()->second, elemCountOutTail,
107	            dataSplitTail_, dataOffsetTail_));
108	    } else {
109	        dataSplitTail_ = dataSplit_;
110	        dataOffsetTail_ = dataOffset_;
111	    }
112	    return HCCL_SUCCESS;
113	}
114	
115	HcclResult InsTempAllReduceNHR::KernelRun(
116	    const OpParam& param, const TemplateDataParams& tempAlgParams, TemplateResource& templateResource)
117	{
118	    HCCL_INFO("[InsTempAllReduceNHR] KernelRun Start.");
119	
120	    CHK_PRT_RET(
121	        subCommRanks_.size() == 0, HCCL_ERROR("[InsTempAllReduceNHR][KernelRun] subCommRanks is empty."),
122	        HcclResult::HCCL_E_INTERNAL);
123	    rankList_ = subCommRanks_.at(0);
124	
125	    CHK_PRT_RET(
126	        rankList_.size() != templateRankSize_,
127	        HCCL_ERROR("[InsTempAllReduceNHR][KernelRun] rank count is invalid in rank list.", myRank_),
128	        HcclResult::HCCL_E_INTERNAL);
129	
130	    // 获取当前rank在rank列表中的序号
131	    CHK_RET(GetAlgRank(myRank_, rankList_, myRankIdx_));
132	
133	    processSize_ = tempAlgParams.sliceSize;
134	    count_ = tempAlgParams.count;
135	    dataType_ = param.DataDes.dataType;
136	    dataTypeSize_ = DATATYPE_SIZE_TABLE[dataType_];
137	    tempAlgParams_ = tempAlgParams;
138	
139	    bool isPcieProtocal = IsPcieProtocol(templateResource.channels); // 判断是否存在pcie链路
140	    isDmaRead_ = isPcieProtocal;                                     // 是否使用Read模式
141	    HCCL_DEBUG("[InsTempAllReduceNHR] Use Dma Read[%d]", isDmaRead_);
142	
143	    if (count_ == 0) {
144	        HCCL_WARNING("[InsTempAllReduceNHR][KernelRun] data count is 0.");
145	        return HcclResult::HCCL_SUCCESS;
146	    }
147	
148	    // 数据切片：向下取整，前N-1个rank各拿sliceSize_，最后rank拿tailSize_
149	    sliceSize_ = (count_ / templateRankSize_) * dataTypeSize_;
150	    tailSize_ = count_ * dataTypeSize_ - sliceSize_ * (templateRankSize_ - 1);
151	
152	    CHK_RET(PrepareDataSplitForMultiChannel(templateResource));
153	    threadNum_ = GetThreadNum();
154	    CHK_PRT_RET(
155	        threadNum_ > templateResource.threads.size(),
156	        HCCL_ERROR(
157	            "[InsTempAllReduceNHR][KernelRun] thread num[%u] more than threads size[%zu].", threadNum_,
158	            templateResource.threads.size()),
159	        HcclResult::HCCL_E_INTERNAL);
160	
161	    // 将数据从input拷贝到hcclBuffer上
162	    CHK_RET(PreCopy(tempAlgParams, templateResource.threads));
163	    if (threadNum_ > 1) {
164	        std::vector<ThreadHandle> subThreads(
165	            templateResource.threads.begin() + 1, templateResource.threads.begin() + threadNum_);
166	        GetNotifyIdxMainToSub(notifyIdxMainToSub_);
167	        CHK_RET(PreSyncInterThreads(templateResource.threads[0], subThreads, notifyIdxMainToSub_));
168	    }
169	    for (u32 channelIdx = 0; channelIdx < channelsPerRank_; channelIdx++) {
170	        // TwoShot算法，第一步ReduceScatter
171	        CHK_RET(RunReduceScatter(tempAlgParams, templateResource.channels, templateResource.threads, channelIdx));
172	        // TwoShot算法，第二步AllGather
173	        CHK_RET(RunAllGather(tempAlgParams, templateResource.channels, templateResource.threads, channelIdx));
174	    }
175	    if (threadNum_ > 1) {
176	        std::vector<ThreadHandle> subThreads(
177	            templateResource.threads.begin() + 1, templateResource.threads.begin() + threadNum_);
178	        GetNotifyIdxSubToMain(notifyIdxSubToMain_);
179	        CHK_RET(PostSyncInterThreads(templateResource.threads[0], subThreads, notifyIdxSubToMain_));
180	    }
181	    // 将数据从hcclBuffer上拷贝到output上
182	    CHK_RET(PostCopy(tempAlgParams, templateResource.threads));
183	
184	    HCCL_INFO("[InsTempAllReduceNHR] KernelRun finished.");
185	
186	    return HcclResult::HCCL_SUCCESS;
187	}
