189	HcclResult
190	InsTempAllReduceNHR::PreCopy(const TemplateDataParams& tempAlgParams, const std::vector<ThreadHandle>& threads) const
191	{
192	    HCCL_INFO("[InsTempAllReduceNHR] PreCopy data from input to hccl buffer");
193	
194	    void* localInBuffPtr = tempAlgParams.buffInfo.inputPtr;
195	    void* localHcclBuffPtr = tempAlgParams.buffInfo.hcclBuff.addr;
196	    u64 inBuffBaseOffset = tempAlgParams.buffInfo.inBuffBaseOff;
197	    u64 hcclBuffBaseOffset = tempAlgParams.buffInfo.hcclBuffBaseOff;
198	
199	    DataSlice copySrcSlice(localInBuffPtr, inBuffBaseOffset, processSize_, count_);
200	    DataSlice copyDstSlice(localHcclBuffPtr, hcclBuffBaseOffset, processSize_, count_);
201	
202	    CHK_RET(LocalCopy(threads.at(0), copySrcSlice, copyDstSlice));
203	
204	    return HcclResult::HCCL_SUCCESS;
205	}
