207	HcclResult InsTempAllReduceNHR::RunReduceScatter(
208	    const TemplateDataParams& tempAlgParams, const std::map<u32, std::vector<ChannelInfo>>& channels,
209	    const std::vector<ThreadHandle>& threads, u32 channelIdx)
210	{
211	    void* localHcclBuffPtr = tempAlgParams.buffInfo.hcclBuff.addr;
212	    u64 hcclBuffBaseOffset = tempAlgParams.buffInfo.hcclBuffBaseOff;
213	
214	    std::vector<NHRStepInfo> stepInfoList;
215	    CHK_RET(GetReduceScatterStepInfoList(stepInfoList));
216	
217	    for (auto& stepInfo : stepInfoList) {
218	        CHK_PRT_RET(
219	            channels.count(rankList_.at(stepInfo.fromRank)) == 0,
220	            HCCL_ERROR(
221	                "[InsTempAllReduceNHR][RunReduceScatter] remoteRank[%u] is not in channels.",
222	                rankList_.at(stepInfo.fromRank)),
223	            HcclResult::HCCL_E_INTERNAL);
224	        CHK_PRT_RET(
225	            channels.count(rankList_.at(stepInfo.toRank)) == 0,
226	            HCCL_ERROR(
227	                "[InsTempAllReduceNHR][RunReduceScatter] remoteRank[%u] is not in channels.",
228	                rankList_.at(stepInfo.toRank)),
229	            HcclResult::HCCL_E_INTERNAL);
230	
231	        const ChannelInfo& recvChannel = channels.at(rankList_.at(stepInfo.fromRank)).at(channelIdx);
232	        const ChannelInfo& sendChannel = channels.at(rankList_.at(stepInfo.toRank)).at(channelIdx);
233	        std::vector<DataSlice> recvSrcSlicesList;
234	        std::vector<DataSlice> sendSrcSlicesList;
235	        std::vector<DataSlice> recvDstSlicesList;
236	        std::vector<DataSlice> sendDstSlicesList;
237	
238	        void* sendRemoteHcclBuffPtr = sendChannel.remoteCclMem.addr;
239	        void* recvRemoteHcclBuffPtr = recvChannel.remoteCclMem.addr;
240	
241	        // 在 nhrInBuffType_ 上进行 ReduceScatter 操作
242	        for (u32 idx = 0; idx < stepInfo.nSlices; ++idx) {
243	            u32 txIdx = stepInfo.txSliceIdxs.at(idx);
244	            u32 rxIdx = stepInfo.rxSliceIdxs.at(idx);
245	            u64 txOff = (txIdx == templateRankSize_ - 1) ? dataOffsetTail_[channelIdx] : dataOffset_[channelIdx];
246	            u64 txSz = (txIdx == templateRankSize_ - 1) ? dataSplitTail_[channelIdx] : dataSplit_[channelIdx];
247	            u64 rxOff = (rxIdx == templateRankSize_ - 1) ? dataOffsetTail_[channelIdx] : dataOffset_[channelIdx];
248	            u64 rxSz = (rxIdx == templateRankSize_ - 1) ? dataSplitTail_[channelIdx] : dataSplit_[channelIdx];
249	            sendSrcSlicesList.emplace_back(
250	                localHcclBuffPtr, hcclBuffBaseOffset + txIdx * sliceSize_ + txOff, txSz, txSz / dataTypeSize_);
251	            sendDstSlicesList.emplace_back(
252	                sendRemoteHcclBuffPtr, hcclBuffBaseOffset + txIdx * sliceSize_ + txOff, txSz, txSz / dataTypeSize_);
253	            recvSrcSlicesList.emplace_back(
254	                recvRemoteHcclBuffPtr, hcclBuffBaseOffset + rxIdx * sliceSize_ + rxOff, rxSz, rxSz / dataTypeSize_);
255	            recvDstSlicesList.emplace_back(
256	                localHcclBuffPtr, hcclBuffBaseOffset + rxIdx * sliceSize_ + rxOff, rxSz, rxSz / dataTypeSize_);
257	        }
258	        SendRecvReduceInfo sendRecvReduceInfo{
259	            {sendChannel, recvChannel},
260	            {{sendSrcSlicesList, sendDstSlicesList}, {recvSrcSlicesList, recvDstSlicesList}},
261	            dataType_,
262	            reduceOp_};
263	
264	        if (isDmaRead_) {
265	            CHK_PRT_RET(
266	                SendRecvReadReduce(sendRecvReduceInfo, threads.at(channelIdx)),
267	                HCCL_ERROR("[InsTempAllReduceNHR] RunReduceScatter SendRecvReduce failed"),
268	                HcclResult::HCCL_E_INTERNAL);
269	        } else {
270	            CHK_PRT_RET(
271	                SendRecvBatchWriteReduce(sendRecvReduceInfo, threads.at(channelIdx)),
272	                HCCL_ERROR("[InsTempAllReduceNHR] RunReduceScatter SendRecvReduce failed"),
273	                HcclResult::HCCL_E_INTERNAL);
274	        }
275	    }
276	
277	    return HcclResult::HCCL_SUCCESS;
278	}
