280	HcclResult InsTempAllReduceNHR::RunAllGather(
281	    const TemplateDataParams& tempAlgParams, const std::map<u32, std::vector<ChannelInfo>>& channels,
282	    const std::vector<ThreadHandle>& threads, u32 channelIdx)
283	{
284	    void* localHcclBuffPtr = tempAlgParams.buffInfo.hcclBuff.addr;
285	    u64 hcclBuffBaseOffset = tempAlgParams.buffInfo.hcclBuffBaseOff;
286	
287	    std::vector<NHRStepInfo> stepInfoList;
288	    CHK_RET(GetAllGatherStepInfoList(stepInfoList));
289	
290	    for (auto& stepInfo : stepInfoList) {
291	        CHK_PRT_RET(
292	            channels.count(rankList_.at(stepInfo.fromRank)) == 0,
293	            HCCL_ERROR(
294	                "[InsTempAllReduceNHR][RunAllGather] remoteRank[%u] is not in channels.",
295	                rankList_.at(stepInfo.fromRank)),
296	            HcclResult::HCCL_E_INTERNAL);
297	        CHK_PRT_RET(
298	            channels.count(rankList_.at(stepInfo.toRank)) == 0,
299	            HCCL_ERROR(
300	                "[InsTempAllReduceNHR][RunAllGather] remoteRank[%u] is not in channels.",
301	                rankList_.at(stepInfo.toRank)),
302	            HcclResult::HCCL_E_INTERNAL);
303	
304	        const ChannelInfo& recvChannel = channels.at(rankList_.at(stepInfo.fromRank)).at(channelIdx);
305	        const ChannelInfo& sendChannel = channels.at(rankList_.at(stepInfo.toRank)).at(channelIdx);
306	        std::vector<DataSlice> sendSrcSlicesList;
307	        std::vector<DataSlice> sendDstSlicesList;
308	        std::vector<DataSlice> recvSrcSlicesList;
309	        std::vector<DataSlice> recvDstSlicesList;
310	
311	        void* sendRemoteHcclBuffPtr = sendChannel.remoteCclMem.addr;
312	        void* recvRemoteHcclBuffPtr = recvChannel.remoteCclMem.addr;
313	
314	        for (u32 idx = 0; idx < stepInfo.nSlices; ++idx) {
315	            u32 txIdx = stepInfo.txSliceIdxs.at(idx);
316	            u32 rxIdx = stepInfo.rxSliceIdxs.at(idx);
317	            u64 txOff = (txIdx == templateRankSize_ - 1) ? dataOffsetTail_[channelIdx] : dataOffset_[channelIdx];
318	            u64 txSz = (txIdx == templateRankSize_ - 1) ? dataSplitTail_[channelIdx] : dataSplit_[channelIdx];
319	            u64 rxOff = (rxIdx == templateRankSize_ - 1) ? dataOffsetTail_[channelIdx] : dataOffset_[channelIdx];
320	            u64 rxSz = (rxIdx == templateRankSize_ - 1) ? dataSplitTail_[channelIdx] : dataSplit_[channelIdx];
321	            sendSrcSlicesList.emplace_back(
322	                localHcclBuffPtr, hcclBuffBaseOffset + txIdx * sliceSize_ + txOff, txSz, txSz / dataTypeSize_);
323	            sendDstSlicesList.emplace_back(
324	                sendRemoteHcclBuffPtr, hcclBuffBaseOffset + txIdx * sliceSize_ + txOff, txSz, txSz / dataTypeSize_);
325	            recvSrcSlicesList.emplace_back(
326	                recvRemoteHcclBuffPtr, hcclBuffBaseOffset + rxIdx * sliceSize_ + rxOff, rxSz, rxSz / dataTypeSize_);
327	            recvDstSlicesList.emplace_back(
328	                localHcclBuffPtr, hcclBuffBaseOffset + rxIdx * sliceSize_ + rxOff, rxSz, rxSz / dataTypeSize_);
329	        }
330	        SendRecvInfo sendRecvInfo{
331	            {sendChannel, recvChannel},
332	            {{sendSrcSlicesList, sendDstSlicesList}, {recvSrcSlicesList, recvDstSlicesList}}};
333	
334	        if (isDmaRead_) {
335	            CHK_PRT_RET(
336	                SendRecvRead(sendRecvInfo, threads.at(channelIdx)),
337	                HCCL_ERROR("[InsTempAllReduceNHR] RunAllGather SendRecv failed"), HcclResult::HCCL_E_INTERNAL);
338	        } else {
339	            CHK_PRT_RET(
340	                SendRecvBatchWrite(sendRecvInfo, threads.at(channelIdx)),
341	                HCCL_ERROR("[InsTempAllReduceNHR] RunAllGather SendRecv failed"), HcclResult::HCCL_E_INTERNAL);
342	        }
343	    }
344	
345	    return HcclResult::HCCL_SUCCESS;
346	}
