348	HcclResult
349	InsTempAllReduceNHR::PostCopy(const TemplateDataParams& tempAlgParams, const std::vector<ThreadHandle>& threads) const
350	{
351	    HCCL_INFO("[InsTempAllReduceNHR][PostCopy] Opbase copy from scratchBuffer to userOut");
352	
353	    void* localHcclBuffPtr = tempAlgParams.buffInfo.hcclBuff.addr;
354	    void* localOutBuffPtr = tempAlgParams.buffInfo.outputPtr;
355	    u64 hcclBuffBaseOffset = tempAlgParams.buffInfo.hcclBuffBaseOff;
356	    u64 outBuffBaseOffset = tempAlgParams.buffInfo.outBuffBaseOff;
357	
358	    DataSlice copySrcSlice(localHcclBuffPtr, hcclBuffBaseOffset, tempAlgParams.sliceSize, tempAlgParams.count);
359	    DataSlice copyDstSlice(localOutBuffPtr, outBuffBaseOffset, tempAlgParams.sliceSize, tempAlgParams.count);
360	
361	    CHK_RET(LocalCopy(threads.at(0), copySrcSlice, copyDstSlice));
362	
363	    return HcclResult::HCCL_SUCCESS;
364	}
