366	// 计算ReduceScatter每轮收发的对端以及slice编号
367	HcclResult InsTempAllReduceNHR::GetReduceScatterStepInfoList(std::vector<NHRStepInfo>& stepInfoList) const
368	{
369	    stepInfoList.clear();
370	
371	    u32 nSteps = GetNHRStepNum();
372	    stepInfoList.resize(nSteps);
373	
374	    for (u32 step = 0; step < nSteps; step++) {
375	        // 计算通信对象
376	        u32 deltaRank = 1 << step;
377	        u32 sendToIdx = (myRankIdx_ + templateRankSize_ - deltaRank) % templateRankSize_;
378	        u32 recvFromIdx = (myRankIdx_ + deltaRank) % templateRankSize_;
379	
380	        // 数据份数和数据编号增量
381	        u32 nSlices = (templateRankSize_ - 1 + (1 << step)) / (1 << (step + 1));
382	        u32 deltaSliceIndex = 1 << (step + 1);
383	        u32 txSliceIdx = sendToIdx;
384	        u32 rxSliceIdx = myRankIdx_;
385	
386	        NHRStepInfo& currStepInfo = stepInfoList[step];
387	        currStepInfo.step = step;
388	        currStepInfo.myRank = myRankIdx_;
389	        currStepInfo.nSlices = nSlices;
390	        currStepInfo.toRank = sendToIdx;
391	        currStepInfo.fromRank = recvFromIdx;
392	
393	        // 计算本rank在每轮收/发中的slice编号
394	        currStepInfo.txSliceIdxs.reserve(nSlices);
395	        currStepInfo.rxSliceIdxs.reserve(nSlices);
396	        for (u32 i = 0; i < nSlices; i++) {
397	            currStepInfo.txSliceIdxs.push_back(txSliceIdx);
398	            currStepInfo.rxSliceIdxs.push_back(rxSliceIdx);
399	            HCCL_DEBUG(
400	                "[InsTempAllReduceNHR][GetStepInfoList] i[%u] txSliceIdx[%u] rxSliceIdx[%u]", i, txSliceIdx,
401	                rxSliceIdx);
402	            txSliceIdx = (txSliceIdx + templateRankSize_ - deltaSliceIndex) % templateRankSize_;
403	            rxSliceIdx = (rxSliceIdx + templateRankSize_ - deltaSliceIndex) % templateRankSize_;
404	        }
405	    }
406	    return HcclResult::HCCL_SUCCESS;
407	}
408	
409	// 计算AllGather每轮收发的对端以及slice编号
410	HcclResult InsTempAllReduceNHR::GetAllGatherStepInfoList(std::vector<NHRStepInfo>& stepInfoList) const
411	{
412	    stepInfoList.clear();
413	
414	    u32 nSteps = GetNHRStepNum();
415	    stepInfoList.resize(nSteps);
416	    for (u32 step = 0; step < nSteps; step++) {
417	        // 计算通信对象
418	        u32 deltaRank = 1 << (nSteps - 1 - step);
419	        u32 sendToIdx = (myRankIdx_ + deltaRank) % templateRankSize_;
420	        u32 recvFromIdx = (myRankIdx_ + templateRankSize_ - deltaRank) % templateRankSize_;
421	
422	        // 数据份数和数据编号增量
423	        u32 nSlices = (templateRankSize_ - 1 + (1 << (nSteps - 1 - step))) / (1 << (nSteps - step));
424	        u32 deltaSliceIndex = 1 << (nSteps - step);
425	        u32 txSliceIdx = myRankIdx_;
426	        u32 rxSliceIdx = (myRankIdx_ - (1 << (nSteps - 1 - step)) + templateRankSize_) % templateRankSize_;
427	
428	        NHRStepInfo& currStepInfo = stepInfoList[step];
429	        currStepInfo.step = step;
430	        currStepInfo.toRank = sendToIdx;
431	        currStepInfo.fromRank = recvFromIdx;
432	        currStepInfo.myRank = myRankIdx_;
433	        currStepInfo.nSlices = nSlices;
434	
435	        // 计算本rank在每轮收/发中的slice编号
436	        currStepInfo.txSliceIdxs.reserve(nSlices);
437	        currStepInfo.rxSliceIdxs.reserve(nSlices);
438	        for (u32 i = 0; i < nSlices; i++) {
439	            currStepInfo.txSliceIdxs.push_back(txSliceIdx);
440	            currStepInfo.rxSliceIdxs.push_back(rxSliceIdx);
441	            HCCL_DEBUG(
442	                "[InsTempAllReduceNHR][GetStepInfoList] i[%u] txSliceIdx[%u] rxSliceIdx[%u]", i, txSliceIdx,
443	                rxSliceIdx);
444	            txSliceIdx = (txSliceIdx + templateRankSize_ - deltaSliceIndex) % templateRankSize_;
445	            rxSliceIdx = (rxSliceIdx + templateRankSize_ - deltaSliceIndex) % templateRankSize_;
446	        }
447	    }
448	    return HcclResult::HCCL_SUCCESS;
449	}
