451	u32 InsTempAllReduceNHR::GetNHRStepNum() const
452	{
453	    u32 nSteps = 0;
454	    for (u32 tmp = templateRankSize_ - 1; tmp != 0; tmp >>= 1, nSteps++) {
455	    }
456	    HCCL_DEBUG("[InsTempAllReduceNHR][GetNHRStepNum] rankSize[%u] nSteps[%u]", templateRankSize_, nSteps);
457	
458	    return nSteps;
459	}
